mapper.select:
SELECT COUNT(*)
FROM USER_BOT_RECOMMEND
WHERE user_id = #{userId}
  AND bot_id = #{botId}

mapper.delete:
DELETE FROM USER_BOT_RECOMMEND
WHERE user_id = #{userId}
  AND bot_id = #{botId}

mapper.update:
UPDATE BOT
SET like_count = like_count + 1
WHERE bot_id = #{botId}

UPDATE BOT
SET like_count = GREATEST(0, like_count - 1)
WHERE bot_id = #{botId}

mapper.select:
